UPDATE BANK_ACCOUNT
SET BANK_NAME = #{bankName}, ACCOUNT_TYPE = #{accountType}
WHERE BANK_ACCOUNT_ID = #{bankAccountId} AND ID = #{id}

UPDATE BANK_ACCOUNT SET BALANCE = BALANCE + #{amount}
WHERE BANK_ACCOUNT_ID = #{bankAccountId} AND ID = #{ownerId}
  AND BALANCE <= 9223372036854775807 - #{amount}
